import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {restoreCoreWorld} from '../../simulations/simulation/ranch-headless.mjs';
import {createCompiledNavigation} from '../../simulations/simulation/compiled/navigation.mjs';
const fixtureBase=process.env.RANCH_FIXTURE_DIR?new URL(process.env.RANCH_FIXTURE_DIR):import.meta.url;
const input=JSON.parse(fs.readFileSync(new URL('./'+(process.env.FIXTURE||'single-100')+'-headless-input.json',fixtureBase))),expected=JSON.parse(fs.readFileSync(new URL('./'+(process.env.FIXTURE||'single-100')+'-headless-expected.json',fixtureBase)));
const json=x=>JSON.parse(JSON.stringify(x));
function close(a,b,path='root'){if(typeof a==='number'&&typeof b==='number'&&!Number.isInteger(a)&&!Number.isInteger(b)){assert(Math.abs(a-b)<1e-10,`${path}: ${a} != ${b}`);return;}if(a&&b&&typeof a==='object'&&typeof b==='object'){assert.deepEqual(Object.keys(a).sort(),Object.keys(b).sort(),path);for(const k of Object.keys(a))close(a[k],b[k],path+'.'+k);return;}assert.deepEqual(a,b,path);}
test('headless core preserves browser domain state; records cross-runtime pose drift',()=>{const core=restoreCoreWorld(input);for(let i=0;i<20;i++)core.step(.3,.05,.3);const actual=json(core.snapshot());close(actual.state,expected.state);const drift=actual.animals.map((a,i)=>Math.hypot(...a.position.map((v,j)=>v-expected.animals[i].position[j])));assert(drift.every(Number.isFinite));console.log('Cross-runtime max pose drift metres',Math.max(...drift));});
test('compiled core replays and conserves resources',async()=>{const compiled=await createCompiledNavigation(fs.readFileSync(new URL('../../simulations/simulation/compiled/navigation.wasm',import.meta.url)));const core=restoreCoreWorld(input,{compiled});const start=core.snapshot(),balanceOf=(s,k)=>s.stock[k]+s.pens.reduce((n,p)=>n+p[k],0)+Object.values(s.activeJobs).reduce((n,j)=>n+(j.resource===k?j.load:0),0)+s.used[k]-s.initial[k]-s.replenished[k];for(let i=0;i<200;i++)core.step(.3,.05,.3);const end=core.snapshot();core.restore(start);for(let i=0;i<200;i++)core.step(.3,.05,.3);assert.deepEqual(core.snapshot(),end);assert(compiled.calls>0);for(const k of Object.keys(core.state.resources)){const s=core.state,balance=s.stock[k]+s.pens.reduce((n,p)=>n+p[k],0)+Object.values(s.activeJobs).reduce((n,j)=>n+(j.resource===k?j.load:0),0)+s.used[k]-s.initial[k]-s.replenished[k];assert(Math.abs(balance-balanceOf(start.state,k))<1e-6,`${k} ${balance}`);}});
test('coarse activity preserves need ticks, save/replay, finite poses and full-detail return',()=>{const core=restoreCoreWorld(input);for(const a of core.actors)a.detail='coarse';const start=core.snapshot();core.step(.3,.05,.3);assert.equal(core.state.seconds,start.state.seconds+.3);assert(core.actors.every(a=>a.pendingSeconds===.3));const saved=core.snapshot();for(let i=0;i<40;i++)core.step(.3,.05,.3);const end=core.snapshot();core.restore(saved);for(let i=0;i<40;i++)core.step(.3,.05,.3);assert.deepEqual(core.snapshot(),end);for(const a of core.actors)a.detail='full';core.step(.3,.05,.3);assert(core.actors.every(a=>a.pendingSeconds===0&&a.body.position.toArray().every(Number.isFinite)));});

test('compiled and JS whole-world states agree within 1e-10 after 20 ticks',async()=>{const compiled=await createCompiledNavigation(fs.readFileSync(new URL('../../simulations/simulation/compiled/navigation.wasm',import.meta.url))),core=restoreCoreWorld(input,{compiled});for(let i=0;i<20;i++)core.step(.3,.05,.3);const reference=restoreCoreWorld(input);for(let i=0;i<20;i++)reference.step(.3,.05,.3);close(json(core.snapshot()),json(reference.snapshot()));});
test('restoring older animal records clears future identities and coarse ticks still update lifecycle',()=>{const core=restoreCoreWorld(input),saved=core.snapshot();for(const p of saved.state.pens)for(const a of p.animals){delete a.storyId;delete a.age;delete a.traits;}core.restore(saved);assert(core.actors.every(a=>a.a.storyId===undefined));for(const a of core.actors)a.detail='coarse';core.step(.3,.05,.3);assert(core.actors.every(a=>Number.isFinite(a.a.age)&&core.state.lifeStories.entities[a.a.storyId]));});
